import{_ as a,o as e,c as n,a2 as t}from"./chunks/framework.Boholvbs.js";const D=JSON.parse('{"title":"xsync-setup(1)","description":"Build the binary, install it locally, and make your first transfer.","frontmatter":{"title":"xsync-setup(1)","description":"Build the binary, install it locally, and make your first transfer.","manual":"xsync-setup(1)","manualName":"Getting started","sectionNumber":"1"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),l={name:"getting-started.md"};function o(p,s,c,i,r,d){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="xsync-setup-1" tabindex="-1">xsync-setup(1) <a class="header-anchor" href="#xsync-setup-1" aria-label="Permalink to &quot;xsync-setup(1)&quot;">​</a></h1><div class="manual-deck"><strong>Getting started</strong><p>Build the binary, install it locally, and make your first transfer.</p></div><h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME {#name}&quot;">​</a></h2><p><strong>xsync-setup</strong> — build and install xsync from a source checkout.</p><h2 id="requirements" tabindex="-1">REQUIREMENTS <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;REQUIREMENTS {#requirements}&quot;">​</a></h2><p>Python 3, a C++20 compiler, CMake, zstd, xxHash, and ICU are required. Ninja is used by the build examples. Run the commands below from the xsync source directory.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Platform</th><th scope="col">Dependencies</th></tr></thead><tbody><tr><td>macOS</td><td>Apple command-line developer tools; Homebrew libraries</td></tr><tr><td>Linux</td><td>C++20 compiler; development packages for zstd, xxHash, and ICU</td></tr></tbody></table></div><h2 id="build" tabindex="-1">BUILD <a class="header-anchor" href="#build" aria-label="Permalink to &quot;BUILD {#build}&quot;">​</a></h2><div class="example-caption">macOS dependencies</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">brew </span><span style="color:#DEDEDE;">install</span><span style="color:#DEDEDE;"> cmake</span><span style="color:#DEDEDE;"> ninja</span><span style="color:#DEDEDE;"> zstd</span><span style="color:#DEDEDE;"> xxhash</span><span style="color:#DEDEDE;"> icu4c</span></span></code></pre></div><div class="example-caption">Debian / Ubuntu dependencies</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">sudo </span><span style="color:#DEDEDE;">apt</span><span style="color:#DEDEDE;"> install</span><span style="color:#DEDEDE;"> build-essential</span><span style="color:#DEDEDE;"> cmake</span><span style="color:#DEDEDE;"> ninja-build</span><span style="color:#DEDEDE;"> python3</span><span style="color:#DEDEDE;"> libzstd-dev</span><span style="color:#DEDEDE;"> libxxhash-dev</span><span style="color:#DEDEDE;"> libicu-dev</span></span></code></pre></div><div class="example-caption">Build and inspect the binary</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">-S</span><span style="color:#DEDEDE;"> .</span><span style="color:#DEDEDE;"> -B</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> -G</span><span style="color:#DEDEDE;"> Ninja</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> build</span></span>
<span class="line"><span style="color:#DEDEDE;">build/xs </span><span style="color:#DEDEDE;">--version</span></span></code></pre></div><h2 id="install" tabindex="-1">INSTALL <a class="header-anchor" href="#install" aria-label="Permalink to &quot;INSTALL {#install}&quot;">​</a></h2><div class="example-caption">Local installation</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> --prefix</span><span style="color:#DEDEDE;"> &quot;$HOME/.local&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">export PATH=</span><span style="color:#DEDEDE;">&quot;$HOME/.local/bin:$PATH&quot;</span></span></code></pre></div><p>This installs the executable, the generated manpage, and zsh completion. Add the PATH setting to your shell configuration if you want it to persist.</p><div class="example-caption">zsh completion — put before your existing compinit setup</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">fpath=(</span><span style="color:#DEDEDE;">&quot;$HOME/.local/share/zsh/site-functions&quot;</span><span style="color:#DEDEDE;"> $fpath)</span></span>
<span class="line"><span style="color:#DEDEDE;">autoload </span><span style="color:#DEDEDE;">-Uz</span><span style="color:#DEDEDE;"> compinit</span></span>
<span class="line"><span style="color:#DEDEDE;">compinit</span></span></code></pre></div><h2 id="first-transfer" tabindex="-1">FIRST TRANSFER <a class="header-anchor" href="#first-transfer" aria-label="Permalink to &quot;FIRST TRANSFER {#first-transfer}&quot;">​</a></h2><div class="example-caption">Copy source contents into the destination</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Replace both paths with your own. Progress is automatic when stderr is a terminal; <code>-P</code> also preserves partial transfer data for a later retry.</p><h2 id="releases" tabindex="-1">RELEASE BUILDS <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;RELEASE BUILDS {#releases}&quot;">​</a></h2><div class="example-caption">Build release artifacts</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--preset</span><span style="color:#DEDEDE;"> release-static</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> --preset</span><span style="color:#DEDEDE;"> release-static</span></span></code></pre></div><p>The release flow produces Linux amd64/arm64 binaries and a macOS universal binary. A macOS host is needed for the macOS output; the documented macOS build also requires Docker, GNU make, and the toolchain. A Linux host can build Linux outputs.</p>`,28)])])}const u=a(l,[["render",o]]);export{D as __pageData,u as default};
